import{Ft as e,St as t,bt as n,ht as r,t as i,vt as a,xt as o,zt as s}from"./chunks/framework.B0CLzZNn.js";import"./chunks/assets.2zH0uHwH.js";var c=JSON.parse(`{"title":"并发限制和重试","description":"","frontmatter":{},"headers":[],"relativePath":"guide/session-related/concurrency-limit-and-retry.md","filePath":"v1/guide/session-related/concurrency-limit-and-retry.md","lastUpdated":1793342047000}`),l={name:`guide/session-related/concurrency-limit-and-retry.md`};function u(i,c,l,u,d,f){let p=s(`NolebasePageProperties`),m=s(`NolebaseGitChangelog`);return e(),a(`div`,null,[c[0]||=r(`h1`,{id:`并发限制和重试`,tabindex:`-1`},[o(`并发限制和重试 `),r(`a`,{class:`header-anchor`,href:`#并发限制和重试`,"aria-label":`Permalink to “并发限制和重试”`},`​`)],-1),t(p),c[1]||=n(`<p>模型适配器提供了并发限制、最大重试次数、超时时间和代理等配置项。这些配置不影响模型的回复质量，但直接关系到请求的稳定性。</p><p><img src="/images/image-33.png" alt="alt text" width="1101" height="588" loading="lazy"></p><h2 id="并发限制" tabindex="-1">并发限制 <a class="header-anchor" href="#并发限制" aria-label="Permalink to “并发限制”">​</a></h2><p>并发限制控制同一时间最多允许发出的请求数量，默认值通常为 <code>1</code>。</p><p>值越小，整体越稳定；值越大，吞吐越高，但更容易触发上游 API 限流或代理拥堵。</p><p>当设置的值为 <code>1</code> 时，适用于以下场景：</p><ul><li>模型平台本身限流较严</li><li>使用了不太稳定的代理</li><li>群内偶尔出现并发消息，但量不大</li></ul><p>此配置下，请求会排队处理，速度较慢但更稳定。</p><p>如果满足以下条件，可以将并发限制提高到 <code>2</code> 或 <code>3</code>：</p><ul><li>上游模型平台并发承受能力较好</li><li>代理稳定</li><li>机器人经常在多个群或多个会话中同时收到请求</li></ul><p>假设并发限制为 <code>1</code>：A 发送消息后 B 紧跟着发送，B 的请求会等 A 处理完毕后才发出。</p><p>假设并发限制为 <code>3</code>：A、B、C 三条请求可以同时发出，回复更快，但也更容易遇到限流或超时。</p><h2 id="错误重试" tabindex="-1">错误重试 <a class="header-anchor" href="#错误重试" aria-label="Permalink to “错误重试”">​</a></h2><p>最大重试次数控制一次请求失败后的补充尝试次数，默认值一般为 <code>3</code>。</p><h3 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to “适用场景”">​</a></h3><p>错误重试主要用于处理临时性故障：</p><ul><li>网络抖动</li><li>代理偶发失败</li><li>上游 API 返回 5xx 错误</li><li>限流擦边，重试即可通过</li></ul><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h3><p>假设最大重试次数为 <code>3</code>：第一次请求失败后，ChatLuna 会再尝试最多 3 次。如果全部失败，才会将错误抛出。</p><h3 id="建议" tabindex="-1">建议 <a class="header-anchor" href="#建议" aria-label="Permalink to “建议”">​</a></h3><ul><li>经常遇到临时网络问题时，保留 <code>2</code> 到 <code>3</code> 次重试</li><li>如果失败原因是配置错误（如 API Key 错误、模型名错误），增加重试次数没有意义</li><li>上游平台限流严格时，过高的重试次数只会延长等待时间</li></ul><h2 id="超时时间" tabindex="-1">超时时间 <a class="header-anchor" href="#超时时间" aria-label="Permalink to “超时时间”">​</a></h2><p>超时时间控制单次请求的最长等待时间，默认值通常为 <code>300000</code> 毫秒（5 分钟）。超过该时间仍未返回结果，请求将按超时处理。</p><p>以下场景可以考虑增大超时时间：</p><ul><li>使用响应较慢的大模型</li><li>经常执行长推理、长上下文任务</li><li>代理本身会带来明显延迟</li></ul><p>但需要注意，超时时间过长会带来以下问题：</p><ul><li>一条失败请求会长时间占用资源</li><li>并发位被持续占用</li><li>用户会以为机器人无响应，实际只是尚未超时。</li></ul><p>假设超时时间为 60 秒：45 秒返回则正常成功，超过 60 秒未返回则按超时失败处理。</p><p>对于长任务，60 秒可能偏短；对于普通聊天，默认的 5 分钟通常足够。</p><h2 id="代理设置" tabindex="-1">代理设置 <a class="header-anchor" href="#代理设置" aria-label="Permalink to “代理设置”">​</a></h2><p>每个模型适配器可以单独配置代理，支持以下三种模式：</p><ul><li>禁用代理：不使用任何代理，直接请求。适用于模型平台本身可以直连的情况。</li><li>遵循全局代理设置：跟随 ChatLuna 主插件的代理配置。适用于多个模型平台使用同一套代理的情况。</li><li>使用自定义代理：为该适配器单独指定代理地址。适用于不同平台需要不同代理，或需要对特定适配器进行调试的情况。</li></ul>`,32),t(m)])}var d=i(l,[[`render`,u]]);export{c as __pageData,d as default};